import { headers } from 'next/headers';
import Script from 'next/script';
import { ConsentBanner } from '@/components/consent-banner';
import './globals.css';

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const nonce = (await headers()).get('x-nonce') ?? undefined; // makes the layout dynamic, as the CSP nonce requires
  return (
    <html lang="en">
      <body>
        {children}
        <ConsentBanner />
        {/* classic script: reads its CSP nonce from document.currentScript */}
        <Script src="/consent.js" strategy="afterInteractive" nonce={nonce} />
      </body>
    </html>
  );
}
