### file: public/consent.js
(function () {
  var TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
  var NONCE = (document.currentScript && document.currentScript.nonce) || '';
  var w = window;
  w.dataLayer = w.dataLayer || [];
  function gtag() { w.dataLayer.push(arguments); }
  var TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
  function state(v) { var o = {}; TYPES.forEach(function (t) { o[t] = v; }); return o; }
  gtag('consent', 'default', state('denied')); // before any Google tag request (PRV-011)
  function stored() { var m = document.cookie.match(/(?:^|; )consent=(granted|denied)/); return m ? m[1] : null; }
  function store(v) {
    document.cookie = 'consent=' + v + '; Max-Age=31536000; Path=/; SameSite=Lax' + (location.protocol === 'https:' ? '; Secure' : '');
  }
  var loaded = false;
  function loadTag() {
    if (loaded) return;
    loaded = true;
    var s = document.createElement('script');
    s.async = true;
    if (NONCE) s.nonce = NONCE;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(TAG_ID);
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', TAG_ID);
  }
  function apply(v) {
    if (v === 'granted') { gtag('consent', 'update', state('granted')); loadTag(); }
    else gtag('consent', 'update', state('denied'));
  }
  var banner = document.getElementById('consent-banner');
  var reopen = document.getElementById('consent-reopen');
  function show(on) { if (banner) banner.hidden = !on; if (reopen) reopen.hidden = on; }
  document.addEventListener('click', function (e) {
    var t = e.target;
    var b = t && t.closest ? t.closest('[data-consent]') : null;
    if (b) { var v = b.getAttribute('data-consent'); store(v); apply(v); show(false); }
    else if (t && t.closest && t.closest('#consent-reopen')) show(true);
  });
  var prior = stored();
  if (prior) { apply(prior); show(false); }
  else { if (navigator.globalPrivacyControl === true) apply('denied'); show(true); }
})();

Next.js 15/16 App Router. 404 must be decided before streaming starts: call notFound() right after the data lookup, before any <Suspense>, and keep loading.tsx out of segments that can 404 (Next docs: after streaming starts the status stays 200). Never turn a data-layer failure into notFound()/null: let it throw so Next answers 5xx. MEASURED on Next 16.4.2 (`next build && next start`, Windows, Turbopack, minimal app): `notFound()` thrown from a request-time page answers status 404, but the HTML body is the `__next_error__` client-render shell (the not-found UI is only in the RSC payload), so the <nav> and home link are NOT in the HTML a crawler or shipgate fetches; a database failure in a page answers 500 with the same shell; an unmatched URL (root not-found.tsx) and a param rejected by `export const dynamicParams = false` plus generateStaticParams() DO return the full HTML 404. So for closed route spaces use `dynamicParams = false` (shown below); for open sets (database slugs) check the HTML with `curl -s` and, if it is the shell, do not assume UX-005 passes (UNPROVEN on Linux and on other 15/16 minors). Render <SiteHeader /> (below) inside the <body> of app/layout.tsx so every error page carries the site's <nav>. On Next 16.3+ error.tsx also receives `retry`; `reset` works on 15 and 16. Verify with `curl -i` against `next build && next start`: unknown URL 404, retired path 410, DB down 500.
