import { notFound } from 'next/navigation';
import { Suspense } from 'react';
import { getPost } from '@/lib/posts';
import { Comments } from './comments';

// Closed set (slugs known at build time): add `export const dynamicParams = false;` and generateStaticParams() so unknown slugs are 404ed by routing with full HTML.
export default async function Page({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params; // Next 15+: params is a Promise
  const post = await getPost(slug); // RTE-006: unknown param -> null
  if (!post) notFound(); // RTE-005: before any <Suspense>, so the status line is 404
  return (
    <article>
      <h1>{post.title}</h1>
      <Suspense fallback={<p>Loading comments</p>}>
        <Comments postId={post.id} />
      </Suspense>
    </article>
  );
}
