import { db } from '@/lib/db'; // your data client
export async function getPost(slug: string) {
  // No try/catch that returns null: a connection error must propagate so Next answers 5xx (RTE-007).
  const rows = await db.query('select id, title from posts where slug = $1', [slug]);
  return rows[0] ?? null;
}
