import { NextResponse, type NextRequest } from 'next/server';

const siteOrigin = new URL(process.env.SITE_URL ?? 'https://example.com').origin;
const hits = new Map<string, number[]>();

function rateLimited(ip: string): boolean {
  const now = Date.now();
  const recent = (hits.get(ip) ?? []).filter((t) => now - t < 10 * 60_000);
  recent.push(now);
  hits.set(ip, recent);
  return recent.length > 5; // SEC-054: more than 5 per 10 minutes -> 429
}

const done = () => NextResponse.redirect(new URL('/contact?sent=1', siteOrigin), 303);

export async function POST(request: NextRequest) {
  // SEC-024: same-origin only (Origin, else Sec-Fetch-Site)
  const origin = request.headers.get('origin');
  if (origin ? origin !== siteOrigin : request.headers.get('sec-fetch-site') === 'cross-site') {
    return new NextResponse('Forbidden', { status: 403 });
  }
  const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'; // trust only behind your own proxy
  if (rateLimited(ip)) return new NextResponse('Too many requests', { status: 429, headers: { 'Retry-After': '600' } });

  const form = await request.formData();
  if (String(form.get('website') ?? '') !== '') return done(); // honeypot filled: look successful, do nothing

  const name = String(form.get('name') ?? '').trim();
  const email = String(form.get('email') ?? '').trim();
  const message = String(form.get('message') ?? '').trim();
  if (!name || name.length > 100 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254 || !message || message.length > 5000) {
    return new NextResponse('Invalid form', { status: 400 });
  }

  try {
    const res = await fetch(process.env.FORM_WEBHOOK_URL!, { // the real destination (UX-001); replace with your provider call
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, email, message }),
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) throw new Error(`webhook ${res.status}`);
  } catch {
    // RES-008: delivery failed -> a 5xx page, never the success state
    return new NextResponse('<!doctype html><html lang="en"><title>Message not sent</title><body><nav><a href="/">Home</a></nav><h1>Your message was not sent</h1><p>Please try again later.</p></body></html>', {
      status: 502,
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }
  return done();
}

Next.js 15/16 App Router. A nonce CSP needs every page rendered per request (Next docs: nonces disable static prerendering, ISR and PPR). The file is proxy.ts exporting `proxy` on Next 16; on Next 15 name it middleware.ts and export `middleware`. Next reads the nonce from the Content-Security-Policy request header and stamps its own scripts; pass it to your own <Script> tags via the x-nonce header (see the consent-loader recipe). Next already sends `Cache-Control: public, max-age=31536000, immutable` for its content-hashed /_next/static assets (it cannot be overridden) and `no-cache`/`max-age=0` revalidation on dynamic HTML, so only your own fingerprinted files need a rule.
### file: proxy.ts
import { NextResponse, type NextRequest } from 'next/server';

export function proxy(request: NextRequest) {
  const nonce = Buffer.from(crypto.randomUUID()).toString('base64'); // fresh per response
  const dev = process.env.NODE_ENV === 'development'; // React needs eval only in dev
  const csp = [
    "default-src 'self'",
    // SEC-075: nonce + strict-dynamic, so host sources are ignored; no wildcard, no unsafe-inline
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${dev ? " 'unsafe-eval'" : ''}`,
    `style-src 'self' ${dev ? "'unsafe-inline'" : `'nonce-${nonce}'`}`,
    "img-src 'self' blob: data:",
    "font-src 'self'",
    "connect-src 'self'", // with analytics add: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com
    "object-src 'none'", // SEC-075(d)
    "base-uri 'self'", // SEC-075(e)
    "form-action 'self'",
    "frame-ancestors 'none'", // SEC-010
    'upgrade-insecure-requests',
  ].join('; ');

  const requestHeaders = new Headers(request.headers);
  requestHeaders.set('x-nonce', nonce);
  requestHeaders.set('Content-Security-Policy', csp);
  const response = NextResponse.next({ request: { headers: requestHeaders } });
  response.headers.set('Content-Security-Policy', csp);
  return response;
}

