import type { NextConfig } from 'next';

const nonProduction = process.env.DEPLOY_ENV !== 'production';

const config: NextConfig = {
  poweredByHeader: false,
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: [
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
          { key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains' }, // HTTPS deployments only
        ],
      },
      // PRF-008: only for files YOU fingerprint (content hash in the name) under public/assets/
      {
        source: '/assets/:path*',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },
      ...(nonProduction
        ? [{ source: '/(.*)', headers: [{ key: 'X-Robots-Tag', value: 'noindex, nofollow' }] }] // IDX-005
        : []),
    ];
  },
};

export default config;

Next.js 15/16 App Router. GET route handlers are dynamic (uncached) by default since Next 15, so the check runs on every request. Replace `db` with the project's data client; keep the contract: 200 when the database answers, 503 when it does not, and nothing but the status word in the body (OPS-002: no versions, commit, dependency or engine names, no error text).
### file: app/api/health/route.ts
import { db } from '@/lib/db'; // your data client (pg, Prisma $queryRaw, Drizzle sql`select 1`, ...)

const NO_STORE = { 'Cache-Control': 'no-store' };

async function databaseUp(): Promise<boolean> {
  try {
    await Promise.race([
      db.query('select 1'),
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 2000)),
    ]);
    return true;
  } catch {
    return false; // never echo the error: it can carry hostnames and versions
  }
}

export async function GET() {
  if (await databaseUp()) return Response.json({ status: 'ok' }, { headers: NO_STORE });
  return Response.json({ status: 'unavailable' }, { status: 503, headers: NO_STORE });
}

Next.js 15/16 App Router. Mode comes from DEPLOY_ENV only; `production` is the one production value. robots.ts and sitemap.ts are cached route handlers unless dynamic, so they are marked force-dynamic (with cacheComponents enabled, drop the export and `await connection()` from next/server inside the function instead). Delete any public/robots.txt and public/sitemap.xml (a static file would shadow these). Non-production: Disallow: /, no Sitemap line, /sitemap.xml answers 404 (proxy), and X-Robots-Tag: noindex, nofollow on every response (the next.config.ts headers() block of the headers recipe; DEPLOY_ENV is read at build time there, so rebuild per environment). Above 50,000 URLs use generateSitemaps() and list the files in robots.txt.
