import type { MetadataRoute } from 'next';
import { siteUrl } from '@/lib/site';
import { getIndexablePosts } from '@/lib/posts'; // only pages that answer 200, are self-canonical and not noindex (IDX-001)

export const dynamic = 'force-dynamic';

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const posts = await getIndexablePosts();
  return [
    { url: `${siteUrl}/` }, // same canonical form as the <link rel="canonical"> tags
    { url: `${siteUrl}/blog` },
    ...posts.map((p) => ({ url: `${siteUrl}/blog/${p.slug}`, lastModified: p.updatedAt })),
  ];
}
